head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > dataType]<br/>컴포넌트에 트리 아이템이 정의되는 형식을 설정합니다.",
    "validation" : [
        "listed 설정 시  트리 아이템을 ItemSet 으로 정의합니다.",
        "트리 아이템을 ItemSet(DataCollection) 으로 정의하는 경우 NodeSet, Label, Value, Depth 항목을 필수로 설정해야 합니다.",   
        "dataType 속성의 기본값은 recursive 이지만, Studio 에서 컴포넌트 생성 시 listed 로 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {        
        dataType : "listed"
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';    
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="아이템 클릭하여 선택 후 getSelectedNode 수행하여 아이템 정보 확인"', '', 'label1');   

    strTarget += '<w2:treeview ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" showCheckbox="true" style="position: relative;width: 200px;">';    
    strTarget += '<w2:itemset nodeset="data:gdl_treeview">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '<w2:depth ref="depth"></w2:depth>';
    strTarget += '<w2:folder ref="folder"></w2:folder>';
    strTarget += '<w2:checkbox ref="checkbox"></w2:checkbox>';
    strTarget += '<w2:checkboxDisabled ref="disabled"></w2:checkboxDisabled>';
    strTarget += '<w2:image ref=""></w2:image>';
    strTarget += '<w2:iconImage ref=""></w2:iconImage>';
    strTarget += '<w2:selectedImage ref=""></w2:selectedImage>';
    strTarget += '<w2:expandedImage ref=""></w2:expandedImage>';
    strTarget += '<w2:leafImage ref=""></w2:leafImage>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:treeview>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "treeview",
        strTarget,
        grp_comp
    );
}



scwin.btn_getSelectedNode_onclick = function (e) {
    let node ='';
    let index = '';

    node = target1.getSelectedNode();    
    index = target1.getSelectedIndex(); 

    wf_body_bottom.getObj("scwin").setReturnValue("return object : "+ node);

    if (node) {
        wf_body_bottom.getObj("scwin").setReturnValue("checked : "+ node.checked);
        wf_body_bottom.getObj("scwin").setReturnValue("checkboxDisabled : "+ node.checkboxDisabled);
        wf_body_bottom.getObj("scwin").setReturnValue("depth : "+ node.depth);
        wf_body_bottom.getObj("scwin").setReturnValue("folder : "+ node.folder);
        wf_body_bottom.getObj("scwin").setReturnValue("index : "+ node.index);
        wf_body_bottom.getObj("scwin").setReturnValue("label : "+ node.label);
        wf_body_bottom.getObj("scwin").setReturnValue("value : "+ node.value);
        wf_body_bottom.getObj("scwin").setReturnValue("parentNode.label : "+ node.parentNode.label);
        wf_body_bottom.getObj("scwin").setReturnValue("childNodes.length : "+ node.childNodes.length);        
    }

    let spanElement = document.querySelector('span[id*="target1_label_'+index+'"]');

    if (spanElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("className: "+ spanElement.className);  
    }        
};



scwin.target1_onclick = function (e) {
    scwin.btn_getSelectedNode_onclick();
}
